INSERT OR IGNORE INTO kitchen_activity(event_key,actor_name,kind,title,action,summary,created_at) VALUES('release-kitchen-controls-2026-10-23','Vanity Vair','website','Simpler editing controls','Site update','Moved photo removal and ad deletion into their edit popups. Ads now have Save and Preview buttons; Preview shows unsaved artwork without saving or activating it. Compact ad details sit beside the artwork. Story photos have an Edit photo button on hover, opening a popup with caption tools and illustrated layout choices.',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
